import fs from "fs"
import path from "path"

// Define paths
const rootChangelogPath = path.join(process.cwd(), "CHANGELOG.md")
const mdxChangelogPath = path.join(
  process.cwd(),
  "content/docs/getting-started/changelog.mdx"
)

// Fumadocs Frontmatter
const frontmatter = `---
title: Changelog
description: Latest updates, components, and improvements in Satisium UI.
---

`

try {
  // Read the root CHANGELOG.md generated by Changesets
  const changelogContent = fs.readFileSync(rootChangelogPath, "utf8")

  // Strip the main "# satisium-ui" title from the auto-generated changelog so it doesn't clash with Fumadocs
  const cleanContent = changelogContent.replace(/^# satisium-ui\n\n/m, "")

  // Write to the Fumadocs MDX file
  fs.writeFileSync(mdxChangelogPath, frontmatter + cleanContent)

  console.log("✅ Successfully synced CHANGELOG.md to Fumadocs changelog.mdx")
} catch (error) {
  console.error("❌ Failed to sync changelog:", error)
}
